def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        return 'D'
    if n == 5:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def = 0
    my_def = 0
    for o in opp:
        if o == 'D':
            opp_def += 1
    for a in my:
        if a == 'D':
            my_def += 1

    opp_last = opp[-1]
    my_last = my[-1]

    opp_d_streak = 0
    for o in reversed(opp):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    if n >= 99:
        return 'D'

    if opp_def >= n * 0.8 and n >= 20:
        if opp_d_streak >= 5 and n % 7 == 0:
            return 'C'
        return 'D'

    if opp_def == 0:
        if my_def == 0:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if opp_d_streak >= 3 and n % 5 == 0:
            return 'C'
        if opp_d_streak == 1:
            return 'C'
        return 'D'

    ret = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i + 1] == 'D':
            ret += 1

    if my_last == 'D':
        if ret >= 2:
            return 'C'
        return 'D'
    else:
        if ret == 0 and my_def > 0:
            return 'D'
        return 'C'
